import React, { useState } from "react";
import { createDelivery } from "../api/deliveryApi";
import { useNavigate } from "react-router-dom";

export default function CreateDeliveryForm() {
  const navigate = useNavigate();
  const [form, setForm] = useState({
    customerId: "",
    lat: "",
    lng: "",
    status: "Assigned",
  });

  const [assignedDriver, setAssignedDriver] = useState<{ id: string, name: string } | null>(null);

const handleSubmit = async (e: React.FormEvent) => {
  e.preventDefault();
  try {
    const res = await createDelivery({
      customerId: form.customerId,
      location: {
        lat: parseFloat(form.lat),
        lng: parseFloat(form.lng),
      },
      status: form.status,
    });

    setAssignedDriver({
      id: res.data.assignedDriver.id,
      name: res.data.assignedDriver.name,
    });

    setForm({ customerId: "", lat: "", lng: "", status: "Assigned" });
    setError("");
  } catch (err) {
    console.error("Error creating delivery:", err);
    setError("❌ Failed to create delivery");
  }
};


  const styles = {
    form: {
      padding: "30px",
      maxWidth: "400px",
      margin: "auto",
      backgroundColor: "#f9f9f9",
      border: "1px solid #ddd",
      borderRadius: "8px",
      boxShadow: "0 2px 6px rgba(0,0,0,0.1)",
    },
    input: {
      width: "100%",
      padding: "10px",
      marginBottom: "15px",
      borderRadius: "4px",
      border: "1px solid #ccc",
      fontSize: "16px",
    },
    select: {
      width: "100%",
      padding: "10px",
      marginBottom: "15px",
      borderRadius: "4px",
      border: "1px solid #ccc",
      fontSize: "16px",
    },
    button: {
      padding: "10px 20px",
      fontSize: "16px",
      backgroundColor: "#007bff",
      color: "#fff",
      border: "none",
      borderRadius: "4px",
      cursor: "pointer",
    },
    backButton: {
      padding: "10px 20px",
      marginLeft: "10px",
      backgroundColor: "#6c757d",
      color: "#fff",
      border: "none",
      borderRadius: "4px",
      cursor: "pointer",
    },
    success: {
      marginTop: "15px",
      fontWeight: "bold",
      color: "#007bff",
    },
    error: {
      marginTop: "15px",
      fontWeight: "bold",
      color: "red",
    },
  };

  return (
    <form onSubmit={handleSubmit} style={styles.form}>
      <h2 style={{ marginBottom: "20px", textAlign: "center" }}>
        Create Delivery
      </h2>

      <input
        style={styles.input}
        type="text"
        name="customerId"
        placeholder="Customer ID"
        value={form.customerId}
        onChange={handleChange}
        required
      />

      <input
        style={styles.input}
        type="text"
        name="lat"
        placeholder="Latitude"
        value={form.lat}
        onChange={handleChange}
        required
      />

      <input
        style={styles.input}
        type="text"
        name="lng"
        placeholder="Longitude"
        value={form.lng}
        onChange={handleChange}
        required
      />

      <select
        style={styles.select}
        name="status"
        value={form.status}
        onChange={handleChange}
      >
        <option value="Assigned">Assigned</option>
        <option value="Pending">Pending</option>
        <option value="In Transit">In Transit</option>
        <option value="Delivered">Delivered</option>
      </select>

      <div>
        <button type="submit" style={styles.button}>
          Create Delivery
        </button>
        <button
          type="button"
          style={styles.backButton}
          onClick={() => navigate("/")}
        >
          ← Back to Dashboard
        </button>
      </div>

      {assignedDriver && (
        <div style={styles.success}>
          ✅ Assigned Driver: <strong>{assignedDriver.name}</strong> (ID:{" "}
          {assignedDriver.id})
        </div>
      )}

      {error && <div style={styles.error}>{error}</div>}
    </form>
  );
}
